#ifdef HAL_IWDG_MODULE_ENABLED
/* Start-up runs before the supervisor task and can take longer than the 1 s IWDG: the
 * first-boot HTTPS key, and on the DK (no FRAM) a new key at every boot, measured 1.1 s
 * from reset to the first scan in a -O0 build (28 Oct, bench). So bsp_init stretches the
 * IWDG to about 8 s and the first kick from a task (thread mode on the process stack,
 * i.e. the scheduler is running) puts back the 1 s from CubeMX. */
static uint32_t wdg_run_prescaler;
static bool wdg_stretched;
static void wdg_set_prescaler(uint32_t pr) {
    if (!wdg_stretched) wdg_run_prescaler = hiwdg.Init.Prescaler;
    hiwdg.Init.Prescaler = pr;
    (void)HAL_IWDG_Init(&hiwdg);               /* already running: reloads PR and kicks */
    wdg_stretched = (pr != wdg_run_prescaler);
}
#endif

/* ---------------- time ---------------- */
extern const uint32_t g_pfnVectors[];          /* the startup file's vector table */

void bsp_init(void) {
    /* Behind the bootloader (boot.h) this image's vectors are at 0x08000000 + PLAT_BOOT_SIZE.
     * SystemInit sets VTOR from VECT_TAB_OFFSET (docs/BOOTLOADER.md); if that was left at 0
     * the interrupts would land in the bootloader, so set it from the link address too. */
    SCB->VTOR = (uint32_t)(uintptr_t)g_pfnVectors;
    __DSB();
    /* DWT cycle counter for scan execution-time statistics */
    (void)HAL_InitTick(0);                     /* starts it if the HAL has not (keeps the count) */
#ifdef HAL_IWDG_MODULE_ENABLED
    wdg_set_prescaler(IWDG_PRESCALER_256);    /* about 8 s until the tasks run: see bsp_wdg_kick */
#endif
}

/* ---------------- HAL timebase ----------------
 * No timer of its own: on the DK a CubeMX TIM6 timebase froze the start-up after a power-up
 * (28 Oct, bench; it ran only once a debugger had attached), while ST's examples and Gary's
 * Smart Filter project, which keep the HAL on SysTick, boot every time. SysTick belongs to
 * FreeRTOS, so the HAL's millisecond count is taken from the DWT cycle counter until the
 * scheduler runs and from the FreeRTOS tick (1 kHz, configTICK_RATE_HZ) after that. These
 * replace the HAL's weak HAL_InitTick and HAL_GetTick; in the .ioc, SYS Timebase = SysTick
 * and no SysTick handler generated (the FreeRTOS port has it). */
static uint32_t boot_ms;                       /* counted before the scheduler started */
static uint32_t boot_rem, boot_last;           /* cycles not yet a whole ms; CYCCNT last seen */
static uint32_t boot_ms_at_start;              /* the count when the scheduler took over */
static bool     sched_seen;

HAL_StatusTypeDef HAL_InitTick(uint32_t TickPriority) {
    (void)TickPriority;                        /* called again after each clock change: keeps the count */
    if (!(DWT->CTRL & DWT_CTRL_CYCCNTENA_Msk)) {
        DCB->DEMCR |= DCB_DEMCR_TRCENA_Msk;
        DWT->CYCCNT = 0;
        DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;
        boot_last = 0;
    }
    return HAL_OK;
}

uint32_t HAL_GetTick(void) {
    if (xTaskGetSchedulerState() != taskSCHEDULER_NOT_STARTED) {
        TickType_t t = __get_IPSR() ? xTaskGetTickCountFromISR() : xTaskGetTickCount();
        if (!sched_seen) {                     /* first call after the start: carry the count on */
            sched_seen = true;
            boot_ms_at_start = boot_ms - (uint32_t)t;
        }
        return boot_ms_at_start + (uint32_t)t;
    }
    /* whole ms at the current clock, so a clock change only affects time from then on;
     * CYCCNT wraps every 17 s at 250 MHz, and start-up calls this far more often */
    uint32_t now = DWT->CYCCNT, per_ms = SystemCoreClock / 1000u;
    boot_rem += now - boot_last;
    boot_last = now;
    if (per_ms) { boot_ms += boot_rem / per_ms; boot_rem %= per_ms; }
    return boot_ms;
}

uint32_t bsp_ms(void) { return HAL_GetTick(); }         /* the HAL timebase above: 1 kHz */
uint32_t bsp_cycles(void) { return DWT->CYCCNT; }
uint32_t bsp_cycles_per_us(void) {
    uint32_t c = SystemCoreClock / 1000000u;
    return c ? c : 1u;
}

/* ---------------- RTC ---------------- */
bool bsp_rtc_write(const bsp_rtc_t *t) {
#ifdef HAL_RTC_MODULE_ENABLED
    if (t->year < 2000u || t->year > 2099u) return false;
    RTC_TimeTypeDef tm = { 0 };
    RTC_DateTypeDef dt = { 0 };
    tm.Hours = t->hours; tm.Minutes = t->minutes; tm.Seconds = t->seconds;
    tm.DayLightSaving = RTC_DAYLIGHTSAVING_NONE; tm.StoreOperation = RTC_STOREOPERATION_RESET;
    dt.Year = (uint8_t)(t->year - 2000u); dt.Month = t->month; dt.Date = t->day; dt.WeekDay = t->dow_iso;
    return HAL_RTC_SetTime(&hrtc, &tm, RTC_FORMAT_BIN) == HAL_OK && HAL_RTC_SetDate(&hrtc, &dt, RTC_FORMAT_BIN) == HAL_OK;
#else
    (void)t;
    return false;
#endif
}

bool bsp_rtc_read(bsp_rtc_t *t) {
#ifdef HAL_RTC_MODULE_ENABLED
    if ((RTC->ICSR & RTC_ICSR_INITS) == 0u) return false;   /* calendar never set */
    RTC_TimeTypeDef tm;
    RTC_DateTypeDef dt;
    /* HAL rule: GetTime must be followed by GetDate to unlock the shadow registers */
    if (HAL_RTC_GetTime(&hrtc, &tm, RTC_FORMAT_BIN) != HAL_OK) return false;
    if (HAL_RTC_GetDate(&hrtc, &dt, RTC_FORMAT_BIN) != HAL_OK) return false;
    t->year = (uint16_t)(2000u + dt.Year);
    t->month = dt.Month;
    t->day = dt.Date;
    t->hours = tm.Hours;                 /* RTC configured for 24-hour format */
    t->minutes = tm.Minutes;
    t->seconds = tm.Seconds;
    t->dow_iso = dt.WeekDay;             /* RTC_WEEKDAY_MONDAY = 1 ... SUNDAY = 7 */
    return true;
#else
    (void)t;
    return false;
#endif
}

/* ---------------- digital I/O ---------------- */
void bsp_io_read(plat_io_in_t *in) {
    uint32_t bits = 0;
    for (unsigned k = 0; k < N_DI; ++k) {
        const bsp_pin_t *p = &di_pins[k];
        bool level = HAL_GPIO_ReadPin(p->port, p->pin) == GPIO_PIN_SET;
        if (level != (p->active_low != 0u)) bits |= 1u << p->ch;
    }
    in->di = bits;
    /* Analog and RTD inputs: no converter on the DK. Reported as not fitted until
     * the board's AFE is chosen (design spec "Full I/O list"). */
    for (unsigned k = 0; k < PLAT_AI_MAX; ++k) { in->ai_raw[k] = 0; in->ai_status[k] = PLAT_AIN_NOT_FITTED; }
    for (unsigned k = 0; k < PLAT_RTD_MAX; ++k) { in->rtd_cdeg[k] = 0; in->rtd_status[k] = PLAT_AIN_NOT_FITTED; }
}

void bsp_io_write(const plat_io_out_t *out) {
    for (unsigned k = 0; k < N_DO; ++k) {
        const bsp_pin_t *p = &do_pins[k];
        bool on = ((out->do_bits >> p->ch) & 1u) != 0u;
        HAL_GPIO_WritePin(p->port, p->pin, (on != (p->active_low != 0u)) ? GPIO_PIN_SET : GPIO_PIN_RESET);
    }
}

void bsp_io_safe_state(void) {
    /* Safe state = every valve output de-energised. The real board must also make
     * outputs default off in hardware (pull-downs on driver inputs), because GPIOs
     * float during reset and before this code runs. */
    plat_io_out_t off = { 0 };
    bsp_io_write(&off);
}

/* ---------------- watchdog and reset ---------------- */
void bsp_wdg_kick(void) {
#ifdef HAL_IWDG_MODULE_ENABLED
    if (wdg_stretched && __get_IPSR() == 0u && (__get_CONTROL() & CONTROL_SPSEL_Msk)) {
        wdg_set_prescaler(wdg_run_prescaler);
        return;
    }
    (void)HAL_IWDG_Refresh(&hiwdg);
#endif
}

bsp_reset_cause_t bsp_reset_cause(void) {
    if (!reset_cause_read) {
        /* PINRSTF is set on every reset (NRST is driven low internally), and BORRSTF
         * also covers POR/PDR, so test in this order. */
        if      (__HAL_RCC_GET_FLAG(RCC_FLAG_IWDGRST)) reset_cause = BSP_RESET_IWDG;
        else if (__HAL_RCC_GET_FLAG(RCC_FLAG_WWDGRST)) reset_cause = BSP_RESET_WWDG;
        else if (__HAL_RCC_GET_FLAG(RCC_FLAG_SFTRST))  reset_cause = BSP_RESET_SOFTWARE;
        else if (__HAL_RCC_GET_FLAG(RCC_FLAG_BORRST))  reset_cause = BSP_RESET_POWER_ON;
        else if (__HAL_RCC_GET_FLAG(RCC_FLAG_PINRST))  reset_cause = BSP_RESET_PIN;
        else                                           reset_cause = BSP_RESET_UNKNOWN;
        __HAL_RCC_CLEAR_RESET_FLAGS();
        reset_cause_read = true;
    }
    return reset_cause;
}

void bsp_system_reset(void) { NVIC_SystemReset(); }

/* ---------------- parameter NVM ----------------
 * I2C FRAM if FRAM_I2C_HANDLE is defined in main.h (the development part),
 * else SPI FRAM if FRAM_CS is labelled, else (bare DK) a RAM stand-in. */
bool nvm_fram_i2c_open(nvm_dev_t *d);    /* nvm_fram_i2c.c */
bool nvm_fram_spi_open(nvm_dev_t *d);    /* nvm_fram_spi.c */

nvm_dev_t *bsp_param_nvm(void) {
    static nvm_dev_t dev;
    if (nvm_fram_i2c_open(&dev)) return &dev;
    if (nvm_fram_spi_open(&dev)) return &dev;
#if !defined(FRAM_CS_Pin) && !defined(FRAM_I2C_HANDLE)
    /* No FRAM in this hardware configuration: RAM stand-in with the same map, so the
     * store logic runs; nothing survives power-off (PSTAT_NVM_VOLATILE). Only as long
     * as the map's last area (META, 1 KB): the part above it is reserved, unused. Build a
     * bare DK with PLAT_FRAM_SIZE=32768u like the DK with its breakout: the stand-in is then
     * 23 KB instead of 91 KB (the 128 KB map), which the RAM budget needs. */
    static uint8_t   mem[STORE_META_ADDR + 1024u];
    static nvm_ram_t ram;
    nvm_ram_init(&dev, &ram, mem, sizeof mem, false);
    return &dev;
#else
    return NULL;          /* FRAM configured but not answering: defaults + calibration alarm */
#endif
}

/* ---------------- data-log flash ---------------- */
bool nor_spi_open(nor_dev_t *d);         /* nor_spi.c */

nor_dev_t *bsp_log_nor(void) {
    static nor_dev_t dev;
    static bool tried, ok;
    if (!tried) { tried = true; ok = nor_spi_open(&dev); }
    if (ok) return &dev;
#if !defined(NOR_CS_Pin)
    /* No log flash in this hardware configuration (the DK's flash is on OCTOSPI):
     * a 32 KB RAM stand-in, so the event log works until power-off (LSTAT_VOLATILE). */
    static uint8_t   mem[32u * 1024u];
    static nor_sim_t sim;
    static bool      init;
    if (!init) { nor_sim_init(&dev, &sim, mem, sizeof mem, false, true); init = true; }
    return &dev;
#else
    return NULL;          /* configured but not answering: logging off, LSTAT shows it */
#endif
}

/* ---------------- program flash banks (firmware update) ---------------- */
struct fw_flash *fw_flash_stm32h5(void);   /* fw_flash_stm32h5.c */
struct fw_flash *bsp_fw_flash(void) { return fw_flash_stm32h5(); }

